#!/usr/bin/env python3
"""Dart arm selection and functional combat documentation; run after golem_scouts."""
import json
from pathlib import Path
A=Path(__file__).resolve().parents[1]/'src/modern/resources/assets/thaumcraft'
for i,loc in enumerate(['en_us','es_es']):
 p=A/f'lang/{loc}.json';v=json.loads(p.read_text());v['golem.thaumcraft.darts']=['Dart launchers','Lanzadardos'][i];v['golem.thaumcraft.ranged']=['Ranged','A distancia'][i]
 v['research.GOLEMCOMBATADV.stage.2']=['Dart arms require this research and cost one aggression module, two dispensers, 32 arrows and one extra simple mechanism in the press. They grant Fighter, Clumsy, Ranged and Fragile. The Fighter addon pays its own second aggression module. Arrows are construction materials: no ammunition is taken per shot, matching the original arms. Darts cannot be picked up. Guard/advanced Guard and Butcher use physical projectiles up to 16 blocks, after 20 ticks of visible aim, with a 20–25 tick shot interval. They need valid tasks, owner/channel, loaded chunks and clear block sight; no ranged melee fallback. Each dart retains its chosen victim, worker and seal and rechecks protection, PvP, redstone, range of the seal and butcher breeding population at impact. Changing the task or disabling the worker invalidates shots. Darts expire after 200 ticks and vanish on block impact; no collateral targets. Other arms keep their previous melee behavior. Native launcher shapes are adapted; original OBJ animations remain pending.','Los brazos Lanzadardos exigen esta investigación y cuestan un módulo de agresión, dos dispensadores, 32 flechas y un mecanismo simple adicional en la prensa. Conceden Luchador, Torpe, A distancia y Frágil. La mejora Luchador paga su segundo módulo de agresión. Las flechas son materiales de construcción: no se consume munición por disparo, como en los brazos originales. Los dardos no se recogen. Vigilar, Vigilar avanzado y Carnicero usan proyectiles físicos hasta 16 bloques, tras 20 ticks de apuntado visible, con intervalo de 20–25 ticks. Exigen tarea válida, propietario/canal, chunks cargados y visión sin bloques; no golpean cuerpo a cuerpo. Cada dardo conserva víctima, gólem y sello y revalida protección, PvP, redstone, área del sello y población reproductora al impactar. Cambiar la tarea o desactivar el gólem invalida los disparos. Caducan a los 200 ticks y desaparecen al chocar con bloques; no cambian a víctimas colaterales. Los otros brazos conservan su combate anterior. Las formas de lanzador son adaptadas; pendientes animaciones OBJ originales.'][i]
 p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
print('Dart arms, non-pickup projectiles and bilingual combat guide generated.')
